const body = $json.body ?? $json;
const dealValue = Number(body.deal_value ?? body.budget ?? 0) || 0;
const hasContact = Boolean(body.email || body.phone || body.whatsapp);
return [{
  json: {
    tenant_slug: body.tenant_slug || $env.TENANT_SLUG || 'unknown',
    name: body.name || body.parent_name || body.contact_name || 'Unknown lead',
    email: body.email || null,
    phone: body.phone || body.whatsapp || null,
    company: body.company || body.business_name || null,
    source: body.source || 'webhook',
    interest: body.interest || body.service || body.message || null,
    deal_value: dealValue,
    score: (dealValue >= 1000 ? 40 : 10) + (hasContact ? 30 : 0) + (body.message ? 20 : 0),
    received_at: new Date().toISOString(),
    raw: body
  }
}];
